+
+var MANIFEST_FILENAME = '.session-input-manifest.json';
+var PENDING_MANIFEST_FILENAME = '.pending-input-manifest.json';
+var SESSION_DELTA_FILENAME = 'session_delta.md';
+var EXCLUDED_SNAPSHOT_FILES = {
