+    '.session-input-manifest.json': true,
+    'session_delta.md': true
+};
+var SESSION_GROUP_MAP = {
+    'story_development': 'dev-write',
+    'bug_development': 'dev-write',
+    'pr_rework': 'dev-write',
+    'pr_review': 'dev-review',
+    'test_case_automation': 'test-write',
