+        return true;
+    } catch (e) {
+        return false;
+    }
+}
+
+function parseFileListResponse(raw) {
+    if (!raw) return [];
+    var parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
+    if (Array.isArray(parsed)) return parsed;
+    return (parsed && Array.isArray(parsed.entries)) ? parsed.entries : [];
+}
