            var childEntries = (sub && sub.entries) || [];
            if (childEntries.length > 0) {
                walk(dir + '/' + name);
            } else if (/\.js$/.test(name)) {
                acc.push(abs.slice(ROOT.length + 1));
            }
        });
    })('js');
    return acc.filter(function (p) { return p.indexOf('js/unit-tests/') !== 0; });
}

