    getPRDiff: getPRDiff,
    detectMergeConflicts: detectMergeConflicts,
    trimLargeTextForInput: trimLargeTextForInput,
    writeInputFile: writeInputFile,
    writeDiscussionsRawJson: writeDiscussionsRawJson,
