function writeInputFile(path, content, label) {
    var text = content || '';
    console.log('Writing ' + label + ' to ' + path + ' (' + text.length + ' chars)');
    file_write({ path: path, content: text });
    console.log('Wrote ' + label + ' to ' + path);
}

/**
 * Write PR context files to input folder.
 * Writes: pr_info.md, pr_diff.txt, pr_discussions.md, pr_discussions_raw.json
 *
 * @param {string}      inputFolder  - input/{ticketKey} path
 * @param {Object}      prDetails    - PR object (GitHub or GitLab, normalized)
 * @param {string}      diff         - git diff text
 * @param {string|null} markdown     - discussions markdown (from githubHelpers.fetchDiscussionsAndRawData)
 * @param {Object|null} rawThreads   - raw threads with IDs (from githubHelpers.fetchDiscussionsAndRawData)
 */
/**
 * gh-806 AC4 + gh-957 AC3: serialize the open threads (already-resolved ones
 * filtered out — a rework/review leg must not spend a duplicate reply pass on
 * closed conversations) WITH the GraphQL census riding along (arm-rule
 * unresolved count + trusted-author breakdown) — the rework leg's input and
 * the SM arm's threads count stay the SAME source.
 */
function writeDiscussionsRawJson(inputFolder, rawThreads) {
    var allThreads = (rawThreads.threads || []);
    var openThreads = allThreads.filter(function(t) { return !!t && t.resolved !== true; });
    if (openThreads.length !== allThreads.length) {
        console.log('Filtered ' + (allThreads.length - openThreads.length) +
            ' already-resolved thread(s) out of pr_discussions_raw.json (gh-806 AC4)');
    }
    writeInputFile(
        inputFolder + '/pr_discussions_raw.json',
        JSON.stringify({ threads: openThreads, census: rawThreads.census || null }, null, 2),
        'pr_discussions_raw.json (' + openThreads.length + ' threads)'
    );
}

function writePRContext(inputFolder, prDetails, diff, markdown, rawThreads) {
    // pr_info.md
    let prInfo = '# Pull Request Information\n\n';
    prInfo += '- **PR #**: ' + prDetails.number + '\n';
    prInfo += '- **URL**: ' + prDetails.html_url + '\n';
    prInfo += '- **Title**: ' + prDetails.title + '\n';
    prInfo += '- **Author**: ' + (prDetails.user ? prDetails.user.login : 'unknown') + '\n';
    prInfo += '- **Branch**: `' + (prDetails.head ? prDetails.head.ref : 'unknown') +
              '` → `' + (prDetails.base ? prDetails.base.ref : 'unknown') + '`\n';
    prInfo += forkCheckout.forkHeadInfoLine(prDetails);
    prInfo += '- **State**: ' + prDetails.state + '\n';
    prInfo += '- **Files Changed**: ' + (prDetails.changed_files || 0) + '\n';
    prInfo += '- **Additions**: +' + (prDetails.additions || 0) + '\n';
    prInfo += '- **Deletions**: -' + (prDetails.deletions || 0) + '\n';
    prInfo += '- **Created**: ' + (prDetails.created_at || '') + '\n';
    prInfo += '- **Updated**: ' + (prDetails.updated_at || '') + '\n';
    if (prDetails.body) {
        prInfo += '\n## PR Description\n\n' + prDetails.body + '\n';
    }
    writeInputFile(inputFolder + '/pr_info.md', prInfo, 'pr_info.md');

    // pr_diff.txt
    var diffContext = trimLargeTextForInput(diff || 'No diff available', 'PR Diff', MAX_PR_DIFF_CONTEXT_CHARS);
    writeInputFile(inputFolder + '/pr_diff.txt', diffContext, 'pr_diff.txt');

    // pr_discussions.md
    if (markdown) {
        writeInputFile(inputFolder + '/pr_discussions.md', markdown, 'pr_discussions.md');
    }

    // pr_discussions_raw.json
    if (rawThreads) {
        writeDiscussionsRawJson(inputFolder, rawThreads);
    }

    console.log('✅ PR context written to', inputFolder);
}

module.exports = {
    cleanCommandOutput: cleanCommandOutput,
    checkoutPRBranch: checkoutPRBranch,
    getPRDiff: getPRDiff,
    detectMergeConflicts: detectMergeConflicts,
    trimLargeTextForInput: trimLargeTextForInput,
    writeInputFile: writeInputFile,
    writeDiscussionsRawJson: writeDiscussionsRawJson,
    writePRContext: writePRContext
};

/**
 * Unit + Integration tests for js/common/sessionDelta.js, preCliReworkSetup.js
 * integration, and scripts/providers/{_common.sh,fa.sh} (gh-1064).
 *
 * Covers:
 *   - AC1: Composite resume prompt embeds session_delta.md inline + pointer to prompt_file
 *   - AC2: Human comment / review thread capture since previous manifest watermark
 *   - AC3: Session-co-located storage (.session-input-manifest.json in session root) & quarantine safety
 *   - AC4: Post-turn commit (promote_pending_session_manifest only on exit 0)
 *   - AC5: Adapter seam & SCM parity (GitHub PR and GitLab MR fixtures produce identical structure)
 *   - AC6: Fallbacks (missing manifest -> FIRST-LEG, corrupt manifest -> CORRUPT-MANIFEST fail-open)
 *   - UT-1..UT-4, IT-1, REG-1
 *
 * Uses: loadModule(), makeRequire(), suite(), test(), assert, cli_execute_command()
 */
'use strict';

var sessionDelta = loadModule('js/common/sessionDelta.js');

function makeMemoryStorage(initialState) {
    var state = Object.assign({
        hasSession: true,
        sessionDir: '/tmp/fake-session-root',
        files: {}
    }, initialState || {});

    return {
        state: state,
        readFile: function(path) {
            return Object.prototype.hasOwnProperty.call(state.files, path) ? state.files[path] : null;
        },
        writeFile: function(path, content) {
            state.files[path] = String(content);
            return true;
        },
        listFiles: function(dirPath) {
            var prefix = dirPath.replace(/\/+$/, '') + '/';
            var out = [];
            Object.keys(state.files).forEach(function(k) {
                if (k.indexOf(prefix) === 0) {
                    var rest = k.substring(prefix.length);
                    if (rest && rest.indexOf('/') === -1) out.push(k);
                }
            });
            return out.sort();
        }
    };
}

suite('sessionDelta — UT-1: buildInputSnapshot & SCM parity (AC5)', function() {

    test('hashes input/<ticket>/ files deterministically while excluding session_delta.md and .pending-input-manifest.json', function() {
        var snap = sessionDelta.buildInputSnapshot('input/GH-1064', {
            recordedAt: '2026-10-20T00:00:00.000Z',
            inputFiles: {
                'pr_info.md': '# Pull Request Information\n\n- **PR #**: 10\n- **Branch**: `feat/x` → `main`\n- **State**: open\n',
                'pr_diff.txt': 'diff --git a/a.js b/a.js\n+var x = 1;\n',
                'rework_base_head.txt': 'sha-leg-1',
                'review_state.md': '# Review State\n\n**Review decision: `CHANGES_REQUESTED`**\n',
                'session_delta.md': 'should be excluded',
                '.pending-input-manifest.json': '{"excluded":true}'
            }
        });

        assert.equal(snap.ticketKey, 'GH-1064');
        assert.equal(snap.headSha, 'sha-leg-1');
        assert.equal(snap.baseBranch, 'main');
        assert.equal(snap.reviewDecision, 'CHANGES_REQUESTED');
        assert.deepEqual(Object.keys(snap.files), [
            'pr_diff.txt',
            'pr_info.md',
            'review_state.md',
            'rework_base_head.txt'
        ]);
        assert.equal(snap.files['session_delta.md'], undefined);
        assert.equal(snap.files['.pending-input-manifest.json'], undefined);
        assert.ok(snap.files['pr_diff.txt'].hash.indexOf('fnv1a64:') === 0);
        assert.equal(snap.files['pr_diff.txt'].size, 37);
    });

    test('AC5 SCM parity: GitHub PR and GitLab MR fixtures produce identical SCM-neutral comment/thread structures', function() {
        var githubRawThreads = JSON.stringify({
            threads: [{
                threadId: 'PRT_kwDO123',
                rootCommentId: 9001,
                author: 'alice',
                date: '2026-10-20',
