                rootCommentId: 'PRT_kwDO123',
                author: 'alice',
                created_at: '2026-10-20',
                path: 'js/app.js',
                line: 42,
                resolved: false,
                body: 'Please handle null input here.'
            }]
        });

        var ghSnap = sessionDelta.buildInputSnapshot('input/PROJ-1', {
